const username = $json.body.erp_username;
const password = $json.body.erp_password;

// Open ERP login page
await $page.goto(
  'https://meta-digitrading.lhike-erp.com/home',
  {
    waitUntil: 'networkidle2',
    timeout: 60000
  }
);

// Wait for login form
await $page.waitForSelector('input[name="txtusername"]', {
  timeout: 30000
});

// Fill credentials
await $page.type('input[name="txtusername"]', username, {
  delay: 50
});

await $page.type('input[name="txtpass"]', password, {
  delay: 50
});

// Submit login form
await Promise.all([
  $page.click('button[type="submit"]'),
  $page.waitForNavigation({
    waitUntil: 'networkidle2',
    timeout: 60000
  }).catch(() => null)
]);

// Check for login error
const loginError = await $page.$('.alert-danger');

if (loginError) {
  const errorText = await $page.evaluate(
    el => el.textContent.trim(),
    loginError
  );

  throw new Error(`Login failed: ${errorText}`);
}

// Optional: verify login succeeded
const currentUrl = $page.url();

if (currentUrl.includes('/login')) {
  throw new Error('Login may have failed. Still on login page.');
}

// Get cookies
const cookies = await $page.cookies();

return [
  {
    json: {
      success: true,
      currentUrl,
      cookies
    }
  }
];

const { cookies } = $json;
if (cookies && cookies.length) {
    await $page.setCookie(...cookies);
}
await $page.setViewport({
    width: 1512,
    height: 982,
    deviceScaleFactor: 1
});

// ---- Extract every column from the current page (excluding Actions/id) ----
async function extractTable() {
    return await $page.evaluate(() => {
        const table =
            document.querySelector('table.dataTable') ||
            document.querySelector('table');
        if (!table) return [];

        const headerCells = Array.from(
            table.querySelectorAll('thead tr:last-child th, thead tr:last-child td')
        ).map(th => th.innerText.trim());

        return Array.from(table.querySelectorAll('tbody tr'))
            .map(tr => {
                const cells = Array.from(tr.querySelectorAll('td'));
                if (!cells.length) return null;

                const row = {};
                cells.forEach((td, i) => {
                    let key = (headerCells[i] && headerCells[i].length)
                        ? headerCells[i]
                        : `col_${i}`;

                    // skip the "Actions" (or "id") column entirely
                    if (/^(actions?|id)$/i.test(key)) return;

                    if (row[key] !== undefined) key = `${key}_${i}`;
                    row[key] = (td.innerText ?? '').trim();
                });

                return row;
            })
            .filter(Boolean);
    });
}

async function isNextDisabled() {
    return await $page.evaluate(() => {
        const nextLi = document.querySelector('li.next');
        return !nextLi || nextLi.classList.contains('disabled');
    });
}

async function tbodySignature() {
    return await $page.evaluate(() => {
        const body = document.querySelector('table.dataTable tbody, table tbody');
        return body ? body.innerText.trim() : '';
    });
}

// ---- Navigate ----
await $page.goto(
    'https://meta-digitrading.lhike-erp.com/intern/view', {
        waitUntil: 'networkidle2',
        timeout: 60000
    }
);
const landedUrl = $page.url();
if (!/\/intern\/view/i.test(landedUrl)) {
    throw new Error(
        `Expected /intern/view but landed on: ${landedUrl} — cookies/session may be invalid.`
    );
}
await $page.waitForSelector('table', { timeout: 60000 });

// ---- Bump page length to 100 to reduce next-clicks ----
try {
    await $page.select('select[name$="_length"]', '100');
    await $page.waitForNetworkIdle({ idleTime: 500, timeout: 30000 });
} catch (_) {}
await $page.waitForSelector('table');

// ---- Paginate through everything ----
const all = [];
const seen = new Set();
let pageNum = 0;
const MAX_PAGES = 1000;

while (true) {
    const pageRows = await extractTable();
    for (const r of pageRows) {
        const key = JSON.stringify(r);
        if (!seen.has(key)) {
            seen.add(key);
            all.push(r);
        }
    }
    if (await isNextDisabled()) break;
    if (++pageNum > MAX_PAGES) break;

    const prevSig = await tbodySignature();
    await $page.click('li.next a');
    await $page.waitForFunction(
        prev => {
            const body = document.querySelector('table.dataTable tbody, table tbody');
            const now = body ? body.innerText.trim() : '';
            return now && now !== prev;
        },
        { timeout: 30000 },
        prevSig
    );
}

return [{
    json: {
        totalRows: all.length,
        rows: all
    }
}];

