// Get intern rows from the previous node
const rawData = $input.first().json.rows;

// Get workspace_id from the Webhook node
const workspaceId = $('Webhook').first().json.body.workspace_id;
const apiKey = $('Webhook').first().json.body.api_key;

// Clean/map each row into a simple variable object
const interns = rawData.map(row => {
  return {
    id: row["Intern & Brands ID"]?.trim(),
    fullName: row["Full Name"]?.trim(),
    companyName: row["Company Name"]?.trim() || "",
    username: row["Username"]?.trim(),
    contactNumber: row["Contact Number"]?.trim(),
    email: row["Email"]?.trim(),
  };
});

// Return a single item with everything nested under "data"
return [
  {
    json: {
      data: {
        workspace_id: workspaceId,
        api_key: apiKey,
        interns: interns,
      },
    },
  },
];
